insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('e9367111-1b13-4956-8da0-6d7533e7d857', 'bc9d3bab-94a4-4278-8a2b-2fd8f2b4e305', $$inleiding: visjes knabbelen aan je huid (afbeelding 1)$$,
   $$biologie-havo-2021-iii-huidcellen-als-visvoer-context1.png$$,
   $$In Kangal, Turkije, zijn warmwaterbronnen waar je jezelf kunt ‘aanbieden’ als visvoer. Als je een hand of een voet in het water steekt, komen er onmiddellijk kleine visjes aan je huid knabbelen (afbeelding 1). De lokale bevolking schrijft een heilzame werking aan dit gedrag van de visjes toe.
afbeelding 1: foto van een voet in het water met daaromheen veel kleine visjes$$, 'inline'),
  ('deef5464-a3ec-4d1c-b5c8-ca7579fa3b1e', 'bc9d3bab-94a4-4278-8a2b-2fd8f2b4e305', $$Garra rufa: dode huidcellen als voedsel; populatie in kreekjes en meren$$,
   $$biologie-havo-2021-iii-huidcellen-als-visvoer-context2.png$$,
   $$Waarschijnlijk helpen de mensen de vissen (Garra rufa) meer dan dat de vissen de mensen helpen. Dode huidcellen vormen namelijk een noodzakelijke voedselbron voor de vissen. Hun oorspronkelijke voedsel − algen en kreeftjes − overleeft minder goed in de warmwaterbronnen. De soort komt van oorsprong voor in kreekjes en meren die in verbinding stonden met de warmwaterbronnen. In de loop van de tijd zijn deze kreekjes en meren gescheiden geraakt van de warmwaterbronnen. De populatie Garra rufa in de kreekjes en meren voedt zich met algen en kreeftenlarven. Als het voedselaanbod beperkt is, eten deze vissen soortgenoten.$$, 'inline'),
  ('4241c5e2-24e2-41e2-980a-cd67efdfbc90', 'bc9d3bab-94a4-4278-8a2b-2fd8f2b4e305', $$tolerantiecurves van Garra rufa en de kreeftjes$$,
   $$biologie-havo-2021-iii-huidcellen-als-visvoer-context3.png$$,
   $$Uit de tekst blijkt dat de tolerantiecurves van Garra rufa en de kreeftjes die hun voedsel vormen, verschillend zijn. In afbeelding 2 zijn drie diagrammen met tolerantiecurves weergegeven.$$, 'inline'),
  ('2df8a08d-1630-429b-b14b-2e1166832953', 'bc9d3bab-94a4-4278-8a2b-2fd8f2b4e305', $$afbeelding 2: drie diagrammen P, Q en R met tolerantiecurves$$,
   $$biologie-havo-2021-iii-huidcellen-als-visvoer-context4.png$$,
   $$afbeelding 2: drie diagrammen (P, Q en R) met de overlevingskans tegen de watertemperatuur voor curve 1 en curve 2. P: curve 1 en 2 liggen bij dezelfde temperaturen, curve 1 is lager dan curve 2. Q: curve 1 ligt bij lagere temperaturen dan curve 2, zonder overlap. R: curve 1 is smal en ligt bij lage temperaturen; curve 2 is breed en loopt door tot hogere temperaturen.$$, 'inline'),
  ('e71e7875-414c-4023-8119-b1b4bb74d369', 'bc9d3bab-94a4-4278-8a2b-2fd8f2b4e305', $$de vissenpopulatie in de warmwaterbronnen kan een nieuwe soort worden$$,
   $$biologie-havo-2021-iii-huidcellen-als-visvoer-context5.png$$,
   $$De vissenpopulatie die nu in de warmwaterbronnen leeft, heeft zich aangepast aan het eten van menselijke huidcellen. Er wordt door wetenschappers gesuggereerd dat de vissen in de warmwaterbronnen als gevolg van hun voedselspecialisatie tot een nieuwe soort zullen evolueren.$$, 'inline'),
  ('e075527c-fa92-42a0-8868-1b2153c1d9be', 'bc9d3bab-94a4-4278-8a2b-2fd8f2b4e305', $$variatie, isolatie en natuurlijke selectie spelen een rol$$,
   $$biologie-havo-2021-iii-huidcellen-als-visvoer-context6.png$$,
   $$Als deze evolutie plaatsvindt, zullen variatie, isolatie en natuurlijke selectie een rol spelen.$$, 'inline'),
  ('20748c66-32c9-4ade-97a9-3bd7acfb172c', '1cf78f3d-471c-405e-abad-069d9558a62f', $$inleiding: appel-allergie van Marianne$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context1.png$$,
   $$Eén hapje van een appel kan bij Marianne al leiden tot jeuk in de mond, lichte zwellingen of zelfs blaren. Zij at dus nooit meer appels. Sinds enige tijd kan Marianne bepaalde appels wel eten.$$, 'inline'),
  ('880e4783-3517-4561-b464-e708698a8514', '1cf78f3d-471c-405e-abad-069d9558a62f', $$primaire en secundaire voedsel-allergie$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context2.png$$,
   $$Soms herkent het immuunsysteem bepaalde stoffen uit de voeding als lichaamsvreemd en gaat daar antistoffen tegen maken. Dit wordt een primaire voedsel-allergie genoemd. Marianne heeft last van appel-allergie. Pollenkorrels van de berk zijn de oorzaak van het ontwikkelen van haar appel-allergie, omdat die pollenkorrels stoffen bevatten die erg lijken op die uit de appel. En omdat Marianne al een allergie tegen berkenpollen (een vorm van hooikoorts) had ontwikkeld, reageert zij ook allergisch op bepaalde appelrassen. Dit wordt een secundaire voedsel-allergie genoemd.$$, 'inline'),
  ('29ce77ff-7df6-4b3a-b659-f040e60ba38e', '1cf78f3d-471c-405e-abad-069d9558a62f', $$twee uitspraken over activering van het immuunsysteem$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context3.png$$,
   $$Het immuunsysteem van Marianne is geactiveerd door stoffen uit de berkenpollen. Twee uitspraken over deze activering van het immuunsysteem zijn:
1 Er is een toename van witte bloedcellen die specifiek op berkenpollen reageren.
2 Er is een toename van de productie van antigenen die aan stoffen uit de berkenpollen binden.$$, 'inline'),
  ('7d0d5d1b-fc86-4f9d-b264-1a19e32b2d11', '1cf78f3d-471c-405e-abad-069d9558a62f', $$verschillen in genen tussen appelrassen$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context4.png$$,
   $$Er is een groot verschil tussen de allergene eigenschappen van verschillende appelrassen. Appels van het ras Santana blijken goed te verdragen door Marianne. Uit onderzoek is duidelijk geworden waar dit verschil tussen appelrassen door wordt veroorzaakt. Kleine verschillen in bepaalde genen leiden ertoe dat genproducten van het ene ras wel allergische reacties oproepen bij mensen met berkenpollenallergie, en van het andere niet.$$, 'inline'),
  ('e1e4ca46-b9ae-4fc3-8bd7-66a118c9bf12', '1cf78f3d-471c-405e-abad-069d9558a62f', $$het appelras Santana ontwikkeld uit Elstar en Priscilla$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context5.png$$,
   $$De Santana wordt veel in de biologische landbouw toegepast omdat het ras resistent is tegen de ziekte appelschurft. De Santana is, zonder gebruik van moderne biotechnologie, ontwikkeld uit de appelrassen Elstar en Priscilla. Elstar heeft een goede smaak maar is niet resistent tegen appelschurft. Priscilla smaakt minder goed, maar is wel resistent tegen appelschurft.$$, 'inline'),
  ('66a2c1b7-4538-4a55-ba57-b1db66750ce0', '1cf78f3d-471c-405e-abad-069d9558a62f', $$secundaire allergieën en bijbehorende primaire allergieën$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context6.png$$,
   $$Er bestaan meerdere secundaire allergieën. Een persoon die allergisch is voor graspollen (hooikoorts), heeft vaak ook een allergie tegen een bepaald voedingsmiddel. Hetzelfde geldt voor allergie tegen de uitwerpselen van de huisstofmijt (huisstofallergie). In tabel 1 staan enkele secundaire allergieën met de bijbehorende primaire allergieën.$$, 'inline'),
  ('9a1dae91-0da6-46f4-9753-8d7c25c04e0b', '1cf78f3d-471c-405e-abad-069d9558a62f', $$tabel 1: secundaire allergieën met primaire allergie$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context7.png$$,
   $$tabel 1 (secundaire allergie: primaire allergie voor berken (hooikoorts) / graspollen (hooikoorts) / huisstofmijt (huisstofallergie)):
aardappel: berken, graspollen
appel: berken, graspollen
garnaal: huisstofmijt
hazelnoot: berken, graspollen
mossel: huisstofmijt
selderij: berken, graspollen
walnoot: berken$$, 'inline'),
  ('081e0b6d-2531-4fd4-8841-1e53f6889b2c', '1cf78f3d-471c-405e-abad-069d9558a62f', $$er bestaat steeds een verwantschap tussen de veroorzakers$$,
   $$biologie-havo-2021-iii-voedsel-allergieen-context8.png$$,
   $$Uit tabel 1 blijkt dat er steeds een verwantschap bestaat tussen de veroorzaker van een secundaire allergie en de veroorzaker van de bijbehorende primaire allergie.$$, 'inline'),
  ('97165e79-8091-445e-8cd6-d0775fd4e19f', '46871c21-dd09-448e-82f3-e350c38912a5', $$inleiding: biologische wijnboer Bernhard$$,
   $$biologie-havo-2021-iii-biologische-wijn-context1.png$$,
   $$Biologische wijnboer Bernhard maakt bij de druiventeelt en de productie van zijn wijnen zoveel mogelijk gebruik van natuurlijke processen.$$, 'inline'),
  ('4612e68c-83e3-4629-a335-7fa4fd2af69d', '46871c21-dd09-448e-82f3-e350c38912a5', $$biologische wijngaard zonder kunstmest en bestrijdingsmiddelen$$,
   $$biologie-havo-2021-iii-biologische-wijn-context2.png$$,
   $$In een biologische wijngaard wordt geen gebruikgemaakt van kunstmest en chemische bestrijdingsmiddelen. Bestrijdingsmiddelen kunnen weliswaar aantasting van de druiven door micro-organismen verminderen, maar veroorzaken ook vervuiling van het grondwater en doden veel bodemorganismen. Bodemleven is juist belangrijk voor de productiviteit van de druivenplanten.$$, 'inline'),
  ('cd2ef464-f908-4180-974c-8ea8bd521859', '46871c21-dd09-448e-82f3-e350c38912a5', $$wormen beluchten de bodem$$,
   $$biologie-havo-2021-iii-biologische-wijn-context3.png$$,
   $$Door de activiteit van wormen, die voornamelijk leven van afgestorven plantenmateriaal, wordt de bodem goed belucht. Deze beluchting is belangrijk voor actief transport in plantenwortels.$$, 'inline'),
  ('469285cf-3430-4497-95a4-7f6a0d6d1071', '46871c21-dd09-448e-82f3-e350c38912a5', $$drie stoffen die in een plantenwortel worden getransporteerd$$,
   $$biologie-havo-2021-iii-biologische-wijn-context4.png$$,
   $$In een plantenwortel vindt transport plaats van onder andere:
1 CO₂
2 water
3 nitraat$$, 'inline'),
  ('e1725e7c-0b18-4c66-9f7f-49db64e0f1da', '46871c21-dd09-448e-82f3-e350c38912a5', $$dierlijke mest en compost: schimmels en bacteriën in de bodem$$,
   $$biologie-havo-2021-iii-biologische-wijn-context5.png$$,
   $$Bernhard maakt gebruik van dierlijke mest en compost in plaats van kunstmest. Daarbij is het belangrijk dat schimmels en bacteriën in de bodem in leven blijven.$$, 'inline'),
  ('1595d6f7-7e76-401d-af16-4ae3fb589d0f', '46871c21-dd09-448e-82f3-e350c38912a5', $$groenbemesting met klaver in symbiose met bacteriën$$,
   $$biologie-havo-2021-iii-biologische-wijn-context6.png$$,
   $$Naast dierlijke mest en compost maakt Bernhard ook gebruik van groenbemesting. Hiervoor zaait hij klaver, die in symbiose leeft met bacteriën in de wortelknolletjes. Door het onderspitten van de klaverplanten wordt de stikstofvoorraad in de bodem aangevuld.$$, 'inline'),
  ('7db12e1c-6d03-4a9d-b1aa-a7fb9efa1993', '46871c21-dd09-448e-82f3-e350c38912a5', $$de stikstofkringloop bij druiventeelt is niet gesloten$$,
   $$biologie-havo-2021-iii-biologische-wijn-context7.png$$,
   $$De bemesting is nodig omdat de stikstofkringloop bij druiventeelt niet gesloten is.$$, 'inline'),
  ('566f77e3-1ae1-48ef-8bc8-69a4cf57cbea', '46871c21-dd09-448e-82f3-e350c38912a5', $$druiven met de hand plukken tegen schimmelvorming$$,
   $$biologie-havo-2021-iii-biologische-wijn-context8.png$$,
   $$Als de druiven rijp zijn, laat Bernhard deze met de hand plukken. Dit is een arbeidsintensieve manier van oogsten, maar hierdoor worden de druiven nauwelijks beschadigd. Deze druiven hebben zo minder last van schimmel na de oogst. Schimmelvorming is nadelig voor de kwaliteit van de wijn.$$, 'inline'),
  ('ffbe2615-9589-49c1-9fd0-356e166b881e', '46871c21-dd09-448e-82f3-e350c38912a5', $$kader: wijn maken met gist en waterslot (afbeelding 1)$$,
   $$biologie-havo-2021-iii-biologische-wijn-context9.png$$,
   $$Bernhard maakt wijn van de geoogste druiven. Nadat hij de druiven geperst heeft, voegt hij gist toe aan het druivensap. De flessen met het mengsel van druivensap en gist sluit hij af met een waterslot (afbeelding 1). Hij zet de flessen op een donkere plaats bij een temperatuur van ongeveer 20 °C. Door gisting ontstaat dan wijn. Die gisting is nogal rumoerig: het borrelt alsof het een werkende vulkaan is. Het waterslot laat het gevormde CO₂ ontsnappen en houdt ongewenste micro-organismen buiten de fles.
afbeelding 1: foto van grote glazen flessen met druivensap en gist, afgesloten met een waterslot$$, 'inline'),
  ('e34352df-10dd-4136-8ac4-581b1f943c60', '46871c21-dd09-448e-82f3-e350c38912a5', $$Bernhard houdt de omstandigheden optimaal$$,
   $$biologie-havo-2021-iii-biologische-wijn-context10.png$$,
   $$Tijdens het proces van wijn maken houdt Bernhard de omstandigheden optimaal.$$, 'inline'),
  ('cebb3138-c190-4cff-9d01-e7de61936a3d', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$inleiding: Sarah is vermoeid, drinkt en plast veel$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context1.png$$,
   $$Wekenlang was Sarah zo vermoeid dat zij ’s middags een dutje moest doen. Ook dronk ze enorme hoeveelheden water, maar had dan daarna nog steeds dorst. Omdat ze veel moest plassen, ging ze vaak wel drie keer per nacht haar bed uit. Na een zoektocht op internet las ze dat deze symptomen karakteristiek zijn voor diabetes.$$, 'inline'),
  ('aa249db1-d0d5-4f32-b26b-bee32e71dc0d', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$veel drinken en plassen door glucose in de voorurine$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context2.png$$,
   $$Veel drinken en veel plassen zijn bij diabetes een gevolg van de verhoogde concentratie glucose in de voorurine en daardoor ook in de urine.$$, 'inline'),
  ('27b83025-c029-48db-97fd-2649ef708b8c', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$afbeelding 1: model van het actief transport van glucose in de nier$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context3.png$$,
   $$Het actief transport van glucose in een deel van de nier bij een gezond persoon wordt in afbeelding 1 weergegeven als een model met trechters en een transportband. Met P is de aanvoer van een vloeistof met glucose weergegeven en met Q de afvoer van een vloeistof. In dit model is de transportband het actief transport van glucose door de membranen heen.
afbeelding 1: model met een trechter P (aanvoer van vloeistof met glucosemoleculen) en een trechter Q (afvoer); een schuine transportband brengt glucosemoleculen van P naar Q$$, 'inline'),
  ('f0cec48b-df2c-43ad-9c56-37856f5d1f9c', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$afbeelding 2 toont drie modellen bij verhoogde glucoseconcentratie$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context4.png$$,
   $$Bij Sarah werd diabetes type 1 geconstateerd. Afbeelding 2 geeft drie modellen weer bij een verhoogde glucoseconcentratie.$$, 'inline'),
  ('e8661e54-5689-466e-b83b-1abf65ef0543', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$afbeelding 2: drie modellen 1, 2 en 3$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context5.png$$,
   $$afbeelding 2: drie modellen (1, 2 en 3) van trechter P, transportband en trechter Q bij een verhoogde glucoseconcentratie in P. Model 1: de transportband vervoert geen glucose; alle glucose blijft in P en stroomt verder. Model 2: de transportband vervoert glucose naar Q; onder de transportband zit geen glucose meer in P. Model 3: de transportband vervoert glucose naar Q, maar onder de transportband stroomt ook nog glucose verder in P.$$, 'inline'),
  ('42a703cc-dc13-4135-9679-19d3fad19647', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$vier onderdelen van de nieren$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context6.png$$,
   $$Vier onderdelen van de nieren zijn:
− gekronkelde nierbuisje
− glomerulus
− haarvat
− verzamelbuisje$$, 'inline'),
  ('dac7f72d-ce47-46ba-be86-21fb52156cd2', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$diabetes type 1: het immuunsysteem vernietigt insulineproducerende cellen$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context7.png$$,
   $$Bij diabetes type 1 valt het eigen immuunsysteem de insulineproducerende cellen in de eilandjes van Langerhans aan en vernietigt deze cellen.$$, 'inline'),
  ('60260d33-93c3-4581-af37-b718eb8e6dba', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$medisch experiment: eilandjes van Langerhans uit stamcellen via de poortader$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context8.png$$,
   $$Sarah deed mee aan een medisch experiment. Hierbij werden eilandjes van Langerhans ingebracht via een infuus in haar poortader. De eilandjes van Langerhans zijn gekweekt uit stamcellen van gezonde donoren. Bij dit experiment wordt onderzocht of het lichaam na de transplantatie zelf opnieuw insuline kan maken.$$, 'inline'),
  ('395c2b6c-4ece-43ff-b33a-cbe9b4ed95bb', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$stamcellen hebben eigenschappen die andere cellen niet hebben$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context9.png$$,
   $$In het experiment zijn stamcellen gebruikt omdat deze cellen eigenschappen hebben die andere lichaamscellen niet hebben.$$, 'inline'),
  ('65b88415-68a9-4ea1-bd79-ffefdb9b6dcd', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$de eilandjes komen in een bepaald orgaan terecht$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context10.png$$,
   $$Na het inbrengen in de poortader komen de eilandjes terecht in een bepaald orgaan.$$, 'inline'),
  ('758dfc55-ebdf-4e07-b5bf-ee820ad35007', '3824d9f3-0191-4eaf-a415-8dbabc755752', $$na de behandeling wordt opnieuw de insulinebehoefte bepaald$$,
   $$biologie-havo-2021-iii-stamcellen-als-behandeling-voor-diabetes-context11.png$$,
   $$In de periode voorafgaand aan haar behandeling moest Sarah regelmatig insuline inspuiten. Na de behandeling werd de hoeveelheid insuline die Sarah moest inspuiten, opnieuw vastgesteld. Na het eten van een gestandaardiseerde hoeveelheid koolhydraten kreeg Sarah een bepaalde stof toegediend, waarna haar bloedglucosegehalte werd gemeten. Hieruit bleek dat de hoeveelheid insuline die Sarah moet spuiten, omlaag kon.$$, 'inline'),
  ('7599b218-efdf-4a52-89ad-2d1c6bc30954', '75a6f866-034e-4e55-a32d-7a204a8d8749', $$inleiding: koraalriffen lijden onder opwarming van het zeewater$$,
   $$biologie-havo-2021-iii-koraalriffen-context1.png$$,
   $$Koraalriffen hebben al jaren te lijden van opwarming van het zeewater door het versterkte broeikaseffect.$$, 'inline'),
  ('cf86015e-044a-4547-9b40-8a5a3ea4fa64', '75a6f866-034e-4e55-a32d-7a204a8d8749', $$kader: poliepen en zoöxanthellen (afbeelding 1)$$,
   $$biologie-havo-2021-iii-koraalriffen-context2.png$$,
   $$Koraal (afbeelding 1) bestaat uit poliepen, die in kolonies samenleven en een gezamenlijk skelet opbouwen van kalk (CaCO₃). Veel koralen hebben een symbiotische relatie ontwikkeld met algen. Deze algen, zoöxanthellen geheten, leven in de cellen van de poliepen en geven de koralen hun prachtige kleuren. Zoöxanthellen produceren organische stoffen waarvan ze het grootste deel aan de poliep afstaan. De zoöxanthellen gebruiken een groot deel van de afvalproducten van de poliepen voor hun stofwisselingsactiviteit.
afbeelding 1: onderwaterfoto van een koraalrif$$, 'inline'),
  ('03ea310c-db17-4f3f-93dd-067ee81d92a8', '75a6f866-034e-4e55-a32d-7a204a8d8749', $$vier stoffen of groepen van stoffen$$,
   $$biologie-havo-2021-iii-koraalriffen-context3.png$$,
   $$Vier stoffen of groepen van stoffen zijn:
1 chlorofyl
2 glucose
3 koolstofdioxide
4 water$$, 'inline'),
  ('f4abf9a9-9c7a-437e-bc1e-bfc173b59974', '75a6f866-034e-4e55-a32d-7a204a8d8749', $$vier processen op een koraalrif met effect op CO₂$$,
   $$biologie-havo-2021-iii-koraalriffen-context4.png$$,
   $$Op een gezond koraalrif vinden processen plaats die effect hebben op de CO₂-concentratie in de atmosfeer:
1 de dissimilatie in de poliepen tijdens de groei
2 de voortgezette assimilatie in de poliepen
3 de vorming van het kalkskelet door de poliepen
4 het afsterven van de zoöxanthellen in de poliepen$$, 'inline'),
  ('01ebbd25-1fb9-4965-94a8-39a6f3aa807b', '75a6f866-034e-4e55-a32d-7a204a8d8749', $$jonge poliepen kunnen verschillende soorten zoöxanthellen opnemen$$,
   $$biologie-havo-2021-iii-koraalriffen-context5.png$$,
   $$In het kader van klimaatverandering wordt onderzoek gedaan naar de temperatuurtolerantie van koralen. Bekend is dat jonge poliepen verschillende soorten zoöxanthellen kunnen opnemen.$$, 'inline'),
  ('367ab32e-7d2b-47a0-96c1-2b460613395a', '9d0bc04c-bcfb-45f1-a8a2-834f9aa6f917', $$inleiding en afbeelding 1: hart met dubbele bypass$$,
   $$biologie-havo-2021-iii-dubbele-bypass-context1.png$$,
   $$Bij een bypassoperatie maakt hartchirurg Layla Faysal een omleiding bij een vernauwde of verstopte kransslagader. Als op twee plaatsen op het hart een kransslagader is vernauwd, maakt ze een dubbele bypass (afbeelding 1).
afbeelding 1: tekening van het hart met twee bypasses; bij de ene bypass staan de pijlen 1 en 2, bij de andere de pijlen 3 en 4 (tegengestelde stroomrichtingen); P, Q, R en S zijn plaatsen op de kransslagaders$$, 'inline'),
  ('f3c8a4aa-e065-4c65-812d-72aa87cc2899', '9d0bc04c-bcfb-45f1-a8a2-834f9aa6f917', $$plaatsen P, Q, R, S en stroomrichtingen 1 t/m 4 in afbeelding 1$$,
   $$biologie-havo-2021-iii-dubbele-bypass-context2.png$$,
   $$In afbeelding 1 zijn met P, Q, R en S mogelijke plaatsen aangegeven waar vernauwing kan optreden in kransslagaders. Met 1, 2, 3 en 4 zijn stroomrichtingen in de bypasses aangegeven.$$, 'inline'),
  ('2a66d0d5-4e10-4c78-bf50-017449ee93d1', '9d0bc04c-bcfb-45f1-a8a2-834f9aa6f917', $$een bloedvat van de patiënt zelf voor de bypass$$,
   $$biologie-havo-2021-iii-dubbele-bypass-context3.png$$,
   $$Voor een bypass gebruikt zij meestal een stukje bloedvat van de patiënt zelf.$$, 'inline'),
  ('cf4d4f4d-f064-4833-b92b-8e7efc6c49b2', '9d0bc04c-bcfb-45f1-a8a2-834f9aa6f917', $$voorkeur voor een slagader uit de borstkas$$,
   $$biologie-havo-2021-iii-dubbele-bypass-context4.png$$,
   $$Dokter Faysal gebruikt voor het maken van een bypass bij voorkeur een slagader uit de borstkas.$$, 'inline'),
  ('a9b9ad56-3daa-416c-8834-9ff0c2473953', '9d0bc04c-bcfb-45f1-a8a2-834f9aa6f917', $$een hartoperatie is complexer dan een blindedarmoperatie$$,
   $$biologie-havo-2021-iii-dubbele-bypass-context5.png$$,
   $$Een hartoperatie is complexer dan een blindedarmoperatie. Dit komt niet alleen doordat het hart een vitaal orgaan is, maar ook omdat de chirurg meer moeite moet doen om het hart te bereiken.$$, 'inline'),
  ('d376bb37-579a-49fa-befd-01e755345243', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$inleiding: ziekte van Alzheimer als oorzaak van dementie$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context1.png$$,
   $$De meest voorkomende oorzaak van dementie is de ziekte van Alzheimer.$$, 'inline'),
  ('8d4d8d8f-efdc-420d-af78-0bd4de94ded4', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$kader: verloop van de ziekte van Alzheimer$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context2.png$$,
   $$Bij de ziekte van Alzheimer gaan sommige zenuwcellen in de hersenen en de verbindingen tussen deze zenuwcellen kapot. Hierdoor kunnen de hersenen niet goed meer functioneren. In de eerste fase wordt het geheugen geleidelijk slechter. In latere fasen krijgt de patiënt problemen met taal en ingewikkelde handelingen en uiteindelijk ontstaan problemen met het uitvoeren van eenvoudige taken.$$, 'inline'),
  ('6be48d2c-e1f8-4159-a88d-f4a45cf98b11', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$Alzheimer door beschadiging en afsterven van zenuwcellen$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context3.png$$,
   $$Alzheimer wordt veroorzaakt door beschadiging en afsterven van zenuwcellen.$$, 'inline'),
  ('b200ed8a-4148-4dc9-aac6-60d42f49c592', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$kader: lang-leven-gen, allel 1 en allel 2, LDL en HDL$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context4.png$$,
   $$Er zijn verschillende genen die het risico op alzheimer beïnvloeden. Een van deze genen beïnvloedt de verhouding tussen ‘slecht cholesterol’ (LDL) en ‘goed cholesterol’ (HDL) in het bloed. Dit gen staat bekend als het ‘lang-leven-gen’. Onderzoekers ontdekten een allel van het lang- leven-gen dat een lagere concentratie LDL, en een hogere concentratie HDL veroorzaakt. Ze vroegen zich af of mensen die dankzij dit gunstige allel langer leven, ook langer geestelijk gezond blijven. Om dat te onderzoeken werd vier jaar lang het geheugen getest van proefpersonen die ouder waren dan 70 jaar en bij de start van het onderzoek geen geheugenproblemen hadden. Ook werd bij hen bepaald of ze het normale allel (allel 1) of het afwijkende, gunstige allel (allel 2) van het lang-leven- gen hadden. Alleen bij mensen die twee kopieën van allel 2 hebben, ging het geheugen minder snel achteruit. Van deze groep kregen ook veel minder mensen alzheimer.$$, 'inline'),
  ('d0a80765-09a2-475a-b277-c5f388c5bbb5', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$over allel 2 worden vier beweringen gedaan$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context5.png$$,
   $$Over allel 2 worden vier beweringen gedaan.$$, 'inline'),
  ('b362206b-9136-4d94-833a-0ba7ef3a0fbf', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$puntmutatie: isoleucine wordt vervangen door valine$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context6.png$$,
   $$Allel 2 is ontstaan door een puntmutatie in het DNA. Deze mutatie leidt tot een eiwit met één afwijkend aminozuur: in plaats van isoleucine wordt valine ingebouwd.$$, 'inline'),
  ('96be6803-9674-4210-ac02-e2d69945ca39', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$het medicijn torcetrapib$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context7.png$$,
   $$Een medicijnfabrikant heeft het medicijn torcetrapib ontwikkeld dat hetzelfde effect zou moeten hebben op de verhouding tussen LDL en HDL als het gunstige allel (allel 2). Gebruik van dit medicijn is mogelijk een manier om slagaderverkalking tegen te gaan.$$, 'inline'),
  ('18942a34-c328-4643-b5b6-d41561d7fe77', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$onderzoek naar torcetrapib bij 850 patiënten$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context8.png$$,
   $$Tijdens een onderzoek naar dit medicijn werd de werking getest op 850 patiënten met slagaderverkalking. Een aantal van de proefpersonen kreeg het torcetrapib toegediend gedurende twee jaar, een andere groep kreeg twee jaar een placebo. Gedurende de periode van het onderzoek werd de LDL- en HDL-concentratie en de bloeddruk gemeten. In afbeelding 1 zijn de resultaten van dit experiment weergegeven.$$, 'inline'),
  ('7f1cb9df-0f48-4a04-9b1f-37c94dea9a6a', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$afbeelding 1: veranderingen in LDL, HDL en bloeddruk na twee jaar$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context9.png$$,
   $$afbeelding 1: Veranderingen in LDL, HDL en bloeddruk na twee jaar, voor controle en torcetrapib. Links de toename van HDL of LDL (mg/dL): LDL controle ongeveer +6, torcetrapib ongeveer −14; HDL controle ongeveer +2, torcetrapib ongeveer +54. Rechts de toename van de bloeddruk (mmHg): controle ongeveer 1,3, torcetrapib ongeveer 4,1.$$, 'inline'),
  ('da5fb201-3847-442a-a778-7af8876a1a69', 'ea1d9974-8da2-4e6c-a8d1-5a2b83366c55', $$twee mogelijke redenen om te stoppen met het onderzoek$$,
   $$biologie-havo-2021-iii-kwieker-ouder-door-genmutatie-context10.png$$,
   $$De medicijnfabrikant stopte na dit experiment met het onderzoek. Redenen om te stoppen kunnen zijn:
1 Het medicijn heeft een ongunstige bijwerking.
2 Het medicijn heeft geen gunstige invloed op de verhouding tussen LDL en HDL.$$, 'inline'),
  ('1b27d233-b08b-4206-a3f2-a8b522291153', '980fb79f-d437-46ba-b7e1-b77ec7a6e573', $$inleiding: methaan uit koeienwinden als energiebron$$,
   $$biologie-havo-2021-iii-methaan-uit-koeienwinden-broeikaseffect-of-duurzame-energie-context1.png$$,
   $$Koeien produceren in hun spijsverteringskanaal grote hoeveelheden brandbaar methaangas (CH₄). Het opvangen (afbeelding 1) en gebruiken van koeienwinden als duurzame energiebron lijkt dan ook een voor de hand liggende gedachte.$$, 'inline'),
  ('4395de94-6769-46c9-bc40-cdff79fee07f', '980fb79f-d437-46ba-b7e1-b77ec7a6e573', $$afbeelding 1: opvangen van gassen uit een koe$$,
   $$biologie-havo-2021-iii-methaan-uit-koeienwinden-broeikaseffect-of-duurzame-energie-context2.png$$,
   $$afbeelding 1: foto van een koe met op haar rug een grote zak waarin gassen uit de pens worden opgevangen$$, 'inline'),
  ('848f2ce3-6c20-45b0-904d-195b45553e41', '980fb79f-d437-46ba-b7e1-b77ec7a6e573', $$kader: voerefficiëntie en methaanproductie in de pens$$,
   $$biologie-havo-2021-iii-methaan-uit-koeienwinden-broeikaseffect-of-duurzame-energie-context3.png$$,
   $$Wetenschappers proberen echter de methaanproductie bij koeien te verkleinen, omdat methaan een zeer sterk broeikasgas is. Hiervoor doen zij onderzoek naar het verband tussen de voerefficiëntie en de methaanproductie van een koe. De voerefficiëntie is de hoeveelheid melk die een koe per kilogram voer produceert. In de pens, de eerste grote maag van een koe, wordt gras afgebroken door micro-organismen. De tussenproducten komen beschikbaar voor de koe. Methaanbacteriën, die zich ook in de pens bevinden, vergisten enkele van die tussenproducten tot methaan. Het methaangas komt vrij via winden en oprispend gas. Per dag produceert een koe honderden liters methaangas.$$, 'inline'),
  ('2c3b6265-009d-4c09-b894-c15a9a5f01f8', '980fb79f-d437-46ba-b7e1-b77ec7a6e573', $$cellulose wordt afgebroken door cellulase$$,
   $$biologie-havo-2021-iii-methaan-uit-koeienwinden-broeikaseffect-of-duurzame-energie-context4.png$$,
   $$De celwanden van cellen van gras bestaan uit cellulose. Cellulose wordt afgebroken door cellulase in de pens van de koe.$$, 'inline'),
  ('03436385-f3e6-45a2-90fd-0c09526b28a0', '980fb79f-d437-46ba-b7e1-b77ec7a6e573', $$microscopisch onderzoek van de maaginhoud$$,
   $$biologie-havo-2021-iii-methaan-uit-koeienwinden-broeikaseffect-of-duurzame-energie-context5.png$$,
   $$Om inzicht te krijgen in de manier waarop bacteriën gras afbreken, bekijkt een wetenschapper een monster van de maaginhoud van een koe met een microscoop. Hij ziet diverse volledige cellen, waaronder cellen van gras, bacteriën en dekweefselcellen van de maagwand van de koe.$$, 'inline'),
  ('182518d9-3655-409b-8f44-1f1af74c09c0', '980fb79f-d437-46ba-b7e1-b77ec7a6e573', $$methaan als brandstof in plaats van aardgas$$,
   $$biologie-havo-2021-iii-methaan-uit-koeienwinden-broeikaseffect-of-duurzame-energie-context6.png$$,
   $$Methaan is een prima brandstof. Bij de verbranding van methaan ontstaat koolstofdioxide en water. Methaan is het hoofdbestanddeel van aardgas dat we voor verwarming van het huis en voor koken gebruiken. Als we in staat zouden zijn om het methaangas uit de koeienmagen te gebruiken als brandstof in plaats van aardgas, zou dat een bijdrage kunnen leveren aan de afremming van het versterkte broeikaseffect.$$, 'inline'),
  ('10005fec-5d7f-422c-8f77-29ea8f0d6551', '980fb79f-d437-46ba-b7e1-b77ec7a6e573', $$verband tussen methaanuitstoot en voerefficiëntie$$,
   $$biologie-havo-2021-iii-methaan-uit-koeienwinden-broeikaseffect-of-duurzame-energie-context7.png$$,
   $$Als de gassen uit de pens van een koe opgevangen worden, is meetbaar hoeveel methaan een koe uitstoot (afbeelding 1). Er blijkt een verband te zijn tussen de methaanuitstoot en de voerefficiëntie. Hoe meer melk een koe per kilogram voer maakt, hoe minder methaan wordt uitgestoten. Naast een effect op het versterkte broeikaseffect heeft een hoge voerefficiëntie ook andere milieuvoordelen.$$, 'inline'),
  ('ec33dd8d-7b9d-4b1a-b116-424221da145e', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$inleiding: vakantie in de zon$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context1.png$$,
   $$Lisa is met haar vriendinnen Jaimy en Julia naar Chersonissos gegaan om lekker vakantie te vieren in de zon. Zonnen is heerlijk, maar te veel zon kan verbranding en huidkanker veroorzaken. Ook de ogen lopen risico.$$, 'inline'),
  ('bd62b569-f703-404f-aaed-d2db09e20a24', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$zonnebril zonder uv-bescherming$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context2.png$$,
   $$Tijdens het shoppen ziet Lisa een mooie zonnebril. Ondanks dat deze bril geen uv-bescherming heeft, wil ze hem toch graag kopen. Jaimy zegt dat door het dragen van zo’n bril de ogen beschadigd kunnen raken.$$, 'inline'),
  ('b07518fb-3b0e-4afd-90f3-3b127af213ad', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$kader: huidtypen, zonkracht en zonnebrandcrème; tabel 1$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context3.png$$,
   $$De meisjes hebben niet allemaal hetzelfde erfelijk bepaalde huidtype. In tabel 1 staat een indeling van de verschillende huidtypen. In de derde kolom staat hoelang iemand onbeschermd in de zon kan verblijven voordat er verbrandingsverschijnselen optreden bij een zonkracht met sterkte 1. De zonkracht kan in Europa variëren tussen 0 en 15.
Lisa heeft huidtype 1 en kan volgens tabel 1 bij zonkracht 1 dus 60 minuten onbeschermd in de zon liggen. Bij een sterkere zonkracht moet de maximale tijd bij zonkracht 1 worden gedeeld door de zonkracht. Voor Lisa betekent dit, dat ze bij zonkracht 3 dan 20 minuten onbeschermd kan zonnen. Deze tijd kan verlengd worden als ze zich insmeert met zonnebrandcrème.
Crème met een factor 20 die dik genoeg is aangebracht, zorgt ervoor dat je 20 keer zo lang in de zon kunt verblijven zonder te verbranden.
tabel 1 (huidtype / omschrijving / maximale tijd onbeschermd in de zon bij zonkracht 1):
1 / zeer lichte huid; verbrandt zeer snel; wordt niet bruin / 60 minuten
2 / lichte huid; verbrandt snel; wordt langzaam bruin / 100 minuten
3 / licht getinte huid; verbrandt zelden; wordt gemakkelijk bruin / 200 minuten
4 / getinte huid; verbrandt bijna nooit; bruint zeer goed / 300 minuten$$, 'inline'),
  ('047c6c3d-c516-461c-80bc-56260232bab4', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$Jaimy heeft huidtype 3 en Julia huidtype 2$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context4.png$$,
   $$Jaimy heeft huidtype 3 en Julia heeft huidtype 2.$$, 'inline'),
  ('898bf123-3aa2-480e-998c-417d5c6cd159', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$zonnebrandcrème factor 30 bij zonkracht 10$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context5.png$$,
   $$De meisjes smeren zich regelmatig goed in met een zonnebrandcrème met factor 30. Op hun eerste stranddag is de zonkracht 10.$$, 'inline'),
  ('40110efd-8b76-4845-8925-d7202726b94f', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$beachvolleybal in de hitte; lauwe of ijskoude douche$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context6.png$$,
   $$Op het strand spelen de vriendinnen een potje beachvolleybal. Het is windstil en de buitentemperatuur is ongeveer 34 ºC. Ze spelen erg fanatiek, maar moeten na enige tijd stoppen omdat Julia zich niet goed voelt door de warmte. Ze wil een ijskoude douche nemen maar Lisa zegt dat ze beter een lauwe douche kan nemen omdat ze dan sneller haar warmte kwijtraakt dan tijdens een ijskoude douche.$$, 'inline'),
  ('a565d853-3907-4c0a-a630-1862d498b12a', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$alcohol en vochtverlies$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context7.png$$,
   $$Als de meisjes iets gaan drinken op het terras valt het ze op dat Nederlanders op Chersonissos sneller aangeschoten raken van alcohol dan thuis in Nederland. Alcohol veroorzaakt dat meer vocht wordt uitgescheiden. De hoge temperatuur leidt tot extra vochtverlies door zweten. Door het toegenomen vochtverlies neemt de alcoholconcentratie in het bloed sneller toe.$$, 'inline'),
  ('0c4e4faf-7516-400e-9064-3c57ff097cbb', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$osmoregulatie en de invloed van alcohol in afbeelding 1$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context8.png$$,
   $$In afbeelding 1 zijn schematisch de osmoregulatie en de invloed van alcohol daarop weergegeven.$$, 'inline'),
  ('09edc03e-c933-4e87-9b77-5a04c4c9b22b', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$afbeelding 1: schema van de osmoregulatie met plaatsen 1, 2 en 3$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context9.png$$,
   $$afbeelding 1: schema van de osmoregulatie. Rekreceptoren in maag → (−) dorstcentrum in hersenschors; osmoreceptoren in hypothalamus → (plaats 1) dorstcentrum; dorstcentrum → (+) drinken; drinken → (+) rekreceptoren in maag; drinken → (plaats 2) osmotische waarde bloed; osmotische waarde bloed → (+) osmoreceptoren in hypothalamus; osmoreceptoren → (+) hypofyse; hypofyse → (+) ADH; alcohol → (plaats 3) op de pijl van hypofyse naar ADH; ADH → (+) waterresorptie in nieren; waterresorptie in nieren → (−) osmotische waarde bloed.
Legenda: + stimulerend of verhogend effect; − remmend of verlagend effect$$, 'inline'),
  ('22b3efe1-3248-40b6-906c-7fe6cb253b1d', '980218ce-42dd-4b7c-81a9-24a91b062e05', $$op plaatsen 1, 2 en 3 moet een + of − worden ingevuld$$,
   $$biologie-havo-2021-iii-zon-en-hitte-context10.png$$,
   $$Op de plaatsen 1, 2 en 3 in afbeelding 1 moet nog een + of een − worden ingevuld.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('ced6eb63-a4bb-4374-b611-fbf6ce015999', 'bc9d3bab-94a4-4278-8a2b-2fd8f2b4e305', 1,
   '[{"domain": "Interactie", "subdomain": "Interactie in ecosystemen"}]'::jsonb,
   '["trofisch niveau", "consument eerste orde", "consument tweede orde", "voedselketen", "kannibalisme"]'::jsonb,
   $$Bepalen tot welke trofische niveaus een vis behoort die algen, kreeftenlarven en soortgenoten eet.$$,
   $$biologie-havo-2021-iii-huidcellen-als-visvoer-vraag1.png$$, $$1p 1 Tot welk trofisch niveau behoort Garra rufa in kreekjes en meren?
A alleen tot de consumenten van de eerste orde
